"""Parametric model generated by caliper.

Edit params.json (or the numbers below) and run:  python model.py
"""

import json
from pathlib import Path

import cadquery as cq

HERE = Path(__file__).resolve().parent


def build(P):
    """Build the part from a flat parameter dict (millimetres)."""
    L, W, T = P["base.length"], P["base.width"], P["base.thickness"]

    # base: base plate, centred on the origin, sitting on Z = 0
    part = cq.Workplane("XY").box(L, W, T, centered=(True, True, False))

    # fillet: rounded plate corners (free)
    r = P["fillet.radius"]
    for sx, sy in [(-1, -1), (1, -1)]:
        cx, cy = sx * L / 2, sy * W / 2
        corner = cq.selectors.BoxSelector((cx - 0.1, cy - 0.1, -0.1), (cx + 0.1, cy + 0.1, T + 0.1))
        part = part.edges(corner).fillet(r)

    # flange: flange standing on the +y edge (height from Z = 0)
    fh, ft = P["flange.height"], P["flange.thickness"]
    part = part.union(cq.Workplane("XY").box(L, ft, fh, centered=(True, True, False)).translate((0, (W / 2 - ft / 2), 0)))

    # h1: through hole in the base
    part = part.cut(cq.Solid.makeCylinder(P["h1.diameter"] / 2, T + 2, cq.Vector(P["h1.x"], P["h1.y"], -1), cq.Vector(0, 0, 1)))

    # h2: through hole in the base
    part = part.cut(cq.Solid.makeCylinder(P["h2.diameter"] / 2, T + 2, cq.Vector(P["h2.x"], P["h2.y"], -1), cq.Vector(0, 0, 1)))

    # fh1: through hole in flange (u along the edge, v above Z = 0)
    u, v, inner = P["fh1.u"], P["fh1.v"], W / 2 - P["flange.thickness"] - 1
    part = part.cut(cq.Solid.makeCylinder(P["fh1.diameter"] / 2, P["flange.thickness"] + 2, cq.Vector(u, inner, v), cq.Vector(0, 1, 0)))

    # fh2: through hole in flange (u along the edge, v above Z = 0)
    u, v, inner = P["fh2.u"], P["fh2.v"], W / 2 - P["flange.thickness"] - 1
    part = part.cut(cq.Solid.makeCylinder(P["fh2.diameter"] / 2, P["flange.thickness"] + 2, cq.Vector(u, inner, v), cq.Vector(0, 1, 0)))

    # slot1: through slot in the base (length is overall, end to end)
    part = part.cut(cq.Workplane("XY").slot2D(P["slot1.length"], P["slot1.width"], P["slot1.angle"]).extrude(T + 2).translate((P["slot1.x"], P["slot1.y"], -1)))

    return part


def load_params():
    return json.loads((HERE / "params.json").read_text(encoding="utf-8"))


if __name__ == "__main__":
    part = build(load_params())
    cq.exporters.export(part, str(HERE / "part.step"))
    cq.exporters.export(part, str(HERE / "part.stl"), tolerance=0.01, angularTolerance=0.1)
    print("wrote part.step and part.stl")
